import java.util.List;
import java.util.Map;

public class ClaimOffice {

    private static final int PROCESSING_FEE_IN_G = 5;

    private static final Map<String, Integer> BASE_PREMIUM_PRICE_LIST_IN_G = Map.of(
            "sword", 100,
            "amulet", 60,
            "staff", 80,
            "potion", 40,
            "rune", 25);

    private final Customer customer;

    public ClaimOffice(Customer customer) {
        this.customer = customer;
    }

    public int basePremium(List<Item> items) {
        return items.stream()
                .mapToInt(this::basePremiumOf)
                .sum();
    }

    private int basePremiumOf(Item item) {
        return BASE_PREMIUM_PRICE_LIST_IN_G.get(item.type());
    }

    public int quote(List<Item> items) {
        return PROCESSING_FEE_IN_G;
    }
}
EOF
